#### Example 2: Monitoring Dashboard Configuration

```json
{
  "widgets": [
    {
      "type": "metric",
      "properties": {
        "title": "Multi-Region Health Overview",
        "region": "us-east-1",
        "metrics": [
          [
            "AWS/Route53",
            "HealthCheckStatus",
            { "label": "Primary Region (us-east-1)", "stat": "Average" }
          ],
          [
            "...",
            { "region": "us-west-2", "label": "Secondary Region (us-west-2)" }
          ]
        ]
      }
    },
    {
      "type": "metric",
      "properties": {
        "title": "Database Replication Lag",
        "metrics": [
          [
            "AWS/RDS",
            "AuroraGlobalDBReplicationLag",
            { "stat": "Average", "label": "Aurora Lag (ms)" }
          ],
          [
            "AWS/DynamoDB",
            "ReplicationLatency",
            { "stat": "Average", "label": "DynamoDB Lag (ms)" }
          ]
        ],
        "yAxis": {
          "left": { "min": 0, "max": 10000, "label": "Latency (ms)" }
        },
        "annotations": {
          "horizontal": [
            {
              "value": 5000,
              "label": "Lag Threshold (5s)",
              "fill": "above",
              "color": "#ff0000"
            }
          ]
        }
      }
    },
    {
      "type": "metric",
      "properties": {
        "title": "S3 Replication Status",
        "metrics": [
          [
            "AWS/S3",
            "ReplicationLatency",
            { "stat": "Maximum", "label": "Max Replication Latency (seconds)" }
          ],
          [
            ".",
            "BytesPendingReplication",
            { "stat": "Sum", "label": "Bytes Pending Replication" }
          ],
          [
            ".",
            "OperationsPendingReplication",
            { "stat": "Sum", "label": "Operations Pending" }
          ]
        ]
      }
    },
    {
      "type": "log",
      "properties": {
        "title": "Recent Failover Events",
        "query": "SOURCE '/aws/lambda/failover-orchestrator'\n| fields @timestamp, @message\n| filter @message like /Failover/\n| sort @timestamp desc\n| limit 20",
        "region": "us-west-2"
      }
    }
  ]
}
```
